#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the always-on deploy of the coder instance. Run on the box from anywhere:
#   ssh -t <box> bash ~/dev/kinby/scripts/deploy-wizard.sh
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "$0")/.."
ENV_FILE="instances/coder/.env"
COMPOSE="docker compose -f compose.yaml -f compose.public.yaml"
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
ROUTINE="implement-ready-issue"
TOTAL_STAGES=6

banner "kinby coder: always-on deploy"

# ── 1. DNS ────────────────────────────────────────────────────────────────
stage "DNS: point a name at this box"
public_ip=$(curl -fsS4 https://ifconfig.me 2>/dev/null || echo "<this box's IPv4>")
say "Caddy needs a DNS name that resolves to this box before it can get a certificate."
ENV_FILE=".env" ask KINBY_DOMAIN "Name for the coder (e.g. kinby.jorgesolerrr.dev):"
step "At your DNS provider, add an A record: ${KINBY_DOMAIN} -> ${public_ip}"
note "The registrar for the domain is yours to open; the wizard cannot guess its URL."
pause "Press Enter once the record is saved."
until [[ "$(dig +short "$KINBY_DOMAIN" A | tail -n1)" == "$public_ip" ]]; do
  warn "${KINBY_DOMAIN} does not resolve to ${public_ip} yet; waiting 20 s"
  sleep 20
done
say "${KINBY_DOMAIN} resolves to ${public_ip}."
ENV_FILE=".env" write_env KINBY_DOMAIN "$KINBY_DOMAIN"

# ── 2. Anthropic API key ──────────────────────────────────────────────────
stage "Anthropic: API key for kinby's own model"
say "The orchestrator runs on the API. The whole supervised run cost 0.12 USD on this meter."
open_url "https://platform.claude.com/settings/keys"
step "Create Key, name it 'kinby coder', copy the value once it is shown."
ask_secret ANTHROPIC_API_KEY "Paste the API key:"
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"

# ── 3. Claude Code token ──────────────────────────────────────────────────
stage "Claude Code: one-year subscription token for the reviewer"
say "Claude Code reviews inside the container with a token from your subscription."
step "In a second terminal on this box run:  claude setup-token"
step "Follow its URL, then copy the token it prints (starts with sk-ant-oat)."
note "The token in instances/coder/.env on your laptop also works; paste that instead."
ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token:"
write_env CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"

# ── 4. GitHub identity ────────────────────────────────────────────────────
stage "GitHub: the identity that pushes branches and comments"
say "A bot account is recommended: GitHub drops a review request whose reviewer is the"
say "PR author, and a separate name marks agent work. Your own token also works today."
if confirm "Use a separate bot account?"; then
  open_url "https://github.com/signup"
  step "Create the bot account (for example kinby-coder) and sign in as it in a private window."
  pause "Press Enter when the bot account exists."
  open_url "https://github.com/${REPO}/settings/access"
  step "As yourself: Add people -> the bot -> Write. Then accept the invitation as the bot."
  pause "Press Enter when the bot has Write access."
  open_url "https://github.com/settings/tokens/new?scopes=repo,workflow,read:org&description=kinby+coder"
  step "As the bot: generate the classic token with repo, workflow, read:org; copy it."
  ask_secret GH_TOKEN "Paste the bot token:"
  ask GIT_USER_NAME "Bot display name for commits:"
  ask GIT_USER_EMAIL "Bot email for commits (its GitHub noreply address works):"
else
  GH_TOKEN=$(gh auth token)
  GIT_USER_NAME=$(git config --global user.name || true)
  GIT_USER_EMAIL=$(git config --global user.email || true)
  say "Using the gh login on this box: $(gh api user -q .login)"
  ask GIT_USER_NAME "Display name for commits:"
  ask GIT_USER_EMAIL "Email for commits:"
fi
write_env GH_TOKEN "$GH_TOKEN"
write_env GIT_USER_NAME "$GIT_USER_NAME"
write_env GIT_USER_EMAIL "$GIT_USER_EMAIL"

# ── 5. Start the stack and register the webhook ───────────────────────────
stage "Start the stack and register the permanent webhook"
GITHUB_WEBHOOK_SECRET=$(_existing GITHUB_WEBHOOK_SECRET || openssl rand -hex 32)
write_env GITHUB_WEBHOOK_SECRET "$GITHUB_WEBHOOK_SECRET"
say "Building the image and starting coder and caddy. This takes a few minutes the first time."
$COMPOSE up --build --detach
until curl -fsS http://127.0.0.1:8787/health >/dev/null 2>&1; do sleep 5; done
say "coder is healthy on 127.0.0.1:8787."
until curl -fsS "https://${KINBY_DOMAIN}/health" >/dev/null 2>&1; do
  note "waiting for Caddy to obtain the certificate for ${KINBY_DOMAIN}"
  sleep 10
done
say "https://${KINBY_DOMAIN}/health answers."
hook_url="https://${KINBY_DOMAIN}/signals/${ROUTINE}"
if gh api "repos/${REPO}/hooks" -q '.[].config.url' | grep -qx "$hook_url"; then
  say "Webhook for ${hook_url} already registered."
else
  gh api --method POST "repos/${REPO}/hooks" \
    -f name=web -F active=true -f 'events[]=issues' -f 'events[]=pull_request' \
    -f "config[url]=${hook_url}" -f config[content_type]=json \
    -f "config[secret]=${GITHUB_WEBHOOK_SECRET}" -f config[insecure_ssl]=0 >/dev/null
  say "Registered the repository webhook for issues and pull_request at ${hook_url}."
fi

# ── 6. Codex login and smoke tests ────────────────────────────────────────
stage "Codex: sign the container in, then smoke-test both clients"
say "Codex keeps its login in the coder-codex volume, so this happens once."
step "Open the URL Codex prints, sign in, and enter the one-time code."
$COMPOSE exec coder codex login --device-auth
say "Smoke tests (each should answer with one word):"
$COMPOSE exec -T coder codex exec --skip-git-repo-check -s read-only "Reply with one word: ready" </dev/null | tail -n1
$COMPOSE exec coder claude -p "Reply with one word: ready"
say "Remaining pieces run without you: the hourly routine, the webhook, and the update cron."

finish
